flowchart TD
    Start((Вход: Покупка /\nПроверка на объекте)) --> S1{"Тип изделия?"}

    S1 -- "Кабель силовой" --> S2{"Маркировка?\nнг(А)-LS / NYM"}
    S1 -- "Провод ПВС/ШВВП" --> Err1["⛔ ОШИБКА: \nПВС в штробу — запрещено"]

    S2 -- "Есть правильная" --> S3{"ГОСТ или ТУ?"}
    S2 -- "Букв нет / Фальсификат" --> Err2["⛔ ОТБРАКОВКА /\nВозврат товара"]

    S3 -- "ГОСТ" --> S4{"Расцветка\nL, N, PE?"}
    S3 -- "ТУ" --> Err3["⛔ ОШИБКА: \nТУ с усечением — риск пожара, возврат"]

    S4 -- "Да" --> Finish{"✅ ДОПУСК\nк монтажу"}
    S4 -- "Нет / Смешана" --> Err2

flowchart TD
  classDef action fill:#f9f,stroke:#333,stroke-width:2px;
  classDef warning fill:#ffcccb,stroke:#f00,stroke-width:2px;
  classDef success fill:#ccffcc,stroke:#0a0,stroke-width:2px;
  classDef delay fill:#cceeff,stroke:#00f,stroke-width:2px,stroke-dasharray: 5 5;

  %% Основной поток
  s["Источник питания сети"] --> monitor("Постоянный мониторинг<br/>действующего значения U")

  %% Логика принятия решения
  monitor --> decision{"Попадает ли<br/>напряжение в допуск?<br/>U_min ... U_сети ... U_max"}

  %% Штатный режим
  decision --"УСТАВКА СОБЛЮДЕНА"--> connected["НАГРУЗКА ВКЛЮЧЕНА<br/>Контакты замкнуты"]
  connected --> monitor

  %% Аварийная ветка
  decision --"АВАРИЙНЫЙ РЕЖИМ"--> fault_alert("Сигнал микроконтроллеру:<br/>перенапряжение или недолёт")
  fault_alert --> cut_off["МГНОВЕННОЕ ОТПРЯЖЕНИЕ<br/>размыкание контактов"]
  cut_off --> off_state["Выходное напряжение = 0<br/>Нагрузка обесточена"]

  %% Цикл восстановления (АПВ)
  off_state --> return_check{"Напряжение во входящей линии<br/>вернулось в норму?"}

  %% Если все еще авария
  return_check --"ПОКА ЕЩЕ АВАРИЯ"--> hold_back["Удержание отключения<br/>защита от частых циклов"]
  hold_back --> return_check

  %% Если норма вернулась - запуск таймера
  return_check --"ДА (ВОЗВРАТ К НОРМЕ)"--> start_apv["СТАРТ ТАЙМЕРА АПВ<br/>(Задержка повторного включения)"]

  %% Таймер и финальный шаг
  start_apv --> timer_wait[("ОТСЧЕТ ЗАДЕРЖКИ T")]
  timer_wait --"Время истекло"--> verify_ok{"Напряжение стабильно?<br/>Нет резких скачков?"}
  verify_ok --"ДА"--> restore["ВОССТАНОВЛЕНИЕ ПИТАНИЯ<br/>замыкание контактов"]
  restore --> connected

  %% Применение стилей к узлам
  class monitor,decision action;
  class fault_alert,cut_off,warn_node warning;
  class connected,success_node success;
  class timer_wait delay;

  classId warn_node fault_alert,cut_off;
  classId success_node connected;
